def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 800:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    capacity = int(supply / WATER_REQ)
    scarcity = capacity <= 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    moderate_prev = 0.0
    for b in prev_bids:
        if b <= 120 and b > moderate_prev:
            moderate_prev = b
    if moderate_prev == 0.0:
        moderate_prev = min(highest_prev, 95.0) if highest_prev > 0 else 55.0

    critical = hp <= 2 or no_water >= 2
    pressured = hp <= 4 or no_water >= 1

    if critical:
        bid = max(110.0, moderate_prev + 18.0)
        if scarcity:
            bid = max(bid, highest_prev + 3.0)
        bid = min(bid, 0.92 * budget)
        return float(max(0.0, min(budget, bid)))

    if pressured:
        bid = max(78.0, moderate_prev + 6.0)
        if scarcity:
            bid += 10.0
        if highest_prev >= 150:
            bid = max(bid, 96.0)
        bid = min(bid, 0.72 * budget)
        return float(max(0.0, min(budget, bid)))

    if scarcity:
        if highest_prev >= 150 or rich_opp >= 2:
            bid = 22.0
        else:
            bid = max(40.0, moderate_prev - 8.0)
    else:
        bid = 34.0
        if moderate_prev > 60:
            bid = max(bid, moderate_prev - 12.0)
        if urgent_opp >= 2:
            bid += 6.0

    reserve_floor = DAILY_SALARY * 0.18
    bid = min(bid, max(reserve_floor, 0.38 * budget))
    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Baseline aggressiveness depends on our HP and no-water streak
    # If we are close to death, we must ensure water.
    if my_hp <= 2 or my_no_water_days >= 2:
        urgency = 0.95
    elif my_hp <= 4 or my_no_water_days >= 1:
        urgency = 0.75
    else:
        urgency = 0.55

    # Competitiveness: use yesterday's max bid as a proxy for how hard they will bid again.
    if prev_bids:
        max_prev_bid = max(prev_bids)
        # If they bid very high yesterday, we slightly undercut but remain competitive.
        if max_prev_bid >= DAILY_SALARY * 1.5:  # ~135
            # Try to match the pressure without overspending.
            target = min(my_budget, max(DAILY_SALARY * 0.65, max_prev_bid * 0.92))
        elif max_prev_bid >= DAILY_SALARY * 1.1:  # ~99
            target = min(my_budget, max(DAILY_SALARY * 0.55, max_prev_bid * 0.85))
        else:
            target = min(my_budget, DAILY_SALARY * urgency)
    else:
        target = min(my_budget, DAILY_SALARY * urgency)

    # Supply-based adjustment: with higher supply relative to our requirement, we can bid less.
    # supply is between 15 and 25; our requirement is 9.
    # If supply is closer to 25, contention is lower.
    if supply >= 21:
        target *= 0.92
    elif supply <= 17:
        target *= 1.05

    # Ensure non-negative and within budget
    if target < 0:
        target = 0.0
    if target > my_budget:
        target = my_budget

    # If budget is tiny, bid what we can.
    if my_budget <= 1.0:
        return my_budget

    # Small floor to avoid bidding 0 when we need water.
    if my_hp > 2 and my_no_water_days == 0:
        # keep it modest
        min_bid = DAILY_SALARY * 0.35
    else:
        min_bid = DAILY_SALARY * 0.55

    bid = max(min_bid, target)
    if bid > my_budget:
        bid = my_budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # In this scenario, supply_range is [15, 25] and WATER_REQ is 13.
    # This means day_context['supply'] // WATER_REQ will always be 1 (e.g., 15 // 13 = 1, 25 // 13 = 1).
    # Therefore, there is effectively only one water slot available, leading to high competition.

    # If no opponents, bid minimally to secure water
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1) 

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid for non-critical situations, considering the high competition
    base_bid = DAILY_SALARY * 0.7 

    # Strategy for high pressure situations:
    # 1. If I missed water yesterday (desperate)
    if my_status['no_water_days'] >= 1:
        # Bid very aggressively, potentially above salary, increasing with more missed days
        return min(my_status['budget'], DAILY_SALARY * 1.05 + (my_status['no_water_days'] * 5)) 

    # 2. If HP is critically low
    if my_status['hp'] <= 2:
        # Bid very aggressively to ensure survival
        return min(my_status['budget'], DAILY_SALARY * 1.1) 

    # Strategy based on opponent's previous bids
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If opponents are bidding very high (close to or above salary),
        # we need to outbid them to secure the single water slot.
        if highest_prev_bid >= DAILY_SALARY * 0.9:
            return min(my_status['budget'], highest_prev_bid + 5) 

        # If opponents are bidding moderately, try to win efficiently by slightly exceeding their bid.
        return min(my_status['budget'], max(base_bid, highest_prev_bid + 1))

    # Fallback for Day 1 or if no previous bids from alive opponents.
    # Given the single-slot competition, the default bid needs to be substantial.
    return min(my_status['budget'], base_bid)
